package com.futahua.papers.mobile;
import android.app.*;import android.os.*;import android.net.Uri;import android.database.sqlite.SQLiteDatabase;import org.json.*;import java.io.*;import java.util.*;
public final class PhoneTargetCheck extends Instrumentation {
 private int passed;private final JSONArray checks=new JSONArray();private PhoneTargets targets;
 private void check(boolean yes,String label)throws Exception{if(!yes)throw new IOException(label);passed++;checks.put(label);Bundle progress=new Bundle();progress.putString("check",label);progress.putInt("passed",passed);sendStatus(1,progress);}
 private void write(File f,String text)throws Exception{try(FileOutputStream out=new FileOutputStream(f)){out.write(text.getBytes("UTF-8"));out.getFD().sync();}}
 private JSONObject waitFor(String id,String status)throws Exception{long end=System.currentTimeMillis()+12000;JSONObject r;do{r=targets.resolve(id);if(status.equals(r.optString("status")))return r;Thread.sleep(200);}while(System.currentTimeMillis()<end);throw new IOException("Expected "+status+" got "+r);}
 private JSONObject waitJob(PhonePeerServer peer,String id)throws Exception{long end=System.currentTimeMillis()+15000;while(System.currentTimeMillis()<end){JSONObject job=peer.localFiles(new JSONObject().put("operation","phone-change-status").put("commandId",id));if(Arrays.asList("completed","failed","uncertain").contains(job.optString("phase")))return job;Thread.sleep(100);}throw new IOException("Phone job deadline");}
 private void clean(File f){if(f.isDirectory()){File[] children=f.listFiles();if(children!=null)for(File child:children)clean(child);}f.delete();}
 @Override public void onCreate(Bundle args){start();}
 @Override public void onStart(){Thread watchdog=new Thread(()->{try{Thread.sleep(20000);StringBuilder trace=new StringBuilder();for(Map.Entry<Thread,StackTraceElement[]> t:Thread.getAllStackTraces().entrySet()){boolean relevant=false;for(StackTraceElement e:t.getValue())if(e.getClassName().startsWith("com.futahua.papers.mobile"))relevant=true;if(relevant){trace.append(t.getKey().getName()).append(": ").append(t.getKey().getState()).append("\n");for(StackTraceElement e:t.getValue())trace.append(e.toString()).append("\n");}}Bundle status=new Bundle();status.putString("diagnostic",trace.toString());sendStatus(2,status);}catch(Exception ignored){}},"target-check-watchdog");watchdog.setDaemon(true);watchdog.start();Bundle output=new Bundle();int code=Activity.RESULT_OK;File fixture=new File(Environment.getExternalStorageDirectory(),"Download/PapersTargetCheck-"+UUID.randomUUID());PhonePeerServer peer=null;String recycledId=null;
 try{check(fixture.mkdirs(),"isolated fixture created");File original=new File(fixture,"before");original.mkdir();File file=new File(original,"report.txt");write(file,"original");PhoneIndex index=PhoneIndex.get(getTargetContext());index.refreshSoon();long end=System.currentTimeMillis()+180000;while(System.currentTimeMillis()<end){JSONObject status=index.call(getTargetContext(),new JSONObject().put("operation","phone-index-status"));if(status.optBoolean("ready")&&!status.optBoolean("refreshing"))break;Thread.sleep(300);}
 targets=PhoneTargets.get(getTargetContext());JSONObject first=targets.track(file);String id=first.getString("targetId");check(first.getString("status").equals("present"),"real phone file enrolled");check(targets.track(file).getString("targetId").equals(id),"repeat import uses same target");
 File renamed=new File(original,"renamed.txt");check(file.renameTo(renamed),"external rename succeeds");JSONObject renamedRef=waitFor(id,"present");check(PhoneStorage.file(Uri.parse(renamedRef.getString("uri"))).equals(renamed.getCanonicalFile()),"reference follows external rename");
 File moved=new File(fixture,"after");check(original.renameTo(moved),"external parent move succeeds");File current=new File(moved,"renamed.txt");JSONObject movedRef=waitFor(id,"present");check(PhoneStorage.file(Uri.parse(movedRef.getString("uri"))).equals(current.getCanonicalFile()),"reference follows parent directory move");
 File copied=new File(moved,"copy.txt");java.nio.file.Files.copy(current.toPath(),copied.toPath());check(!targets.track(copied).getString("targetId").equals(id),"same bytes copied to another file have a separate target");
 check(current.delete(),"external deletion succeeds");waitFor(id,"deleted");check(true,"observed disk deletion confirms target tombstone");write(current,"different file");check(targets.resolve(id).getString("status").equals("deleted"),"reused filename does not resurrect deleted target");check(!targets.track(current).getString("targetId").equals(id),"new file at old name receives new identity");
peer=new PhonePeerServer(getTargetContext());JSONObject copyRef=targets.track(copied),otherRef=targets.track(current);String denied=UUID.randomUUID().toString();peer.localFiles(new JSONObject().put("operation","phone-change").put("action","delete").put("uri",copyRef.getString("uri")).put("targetId",otherRef.getString("targetId")).put("expectedRevision",otherRef.getLong("revision")).put("commandId",denied));check(waitJob(peer,denied).getString("phase").equals("failed")&&copied.exists(),"mismatched reference cannot recycle another file");recycledId=UUID.randomUUID().toString();peer.localFiles(new JSONObject().put("operation","phone-change").put("action","delete").put("uri",copyRef.getString("uri")).put("targetId",copyRef.getString("targetId")).put("expectedRevision",copyRef.getLong("revision")).put("commandId",recycledId));check(waitJob(peer,recycledId).getString("phase").equals("completed"),"checked recycle job completes");check(targets.resolve(copyRef.getString("targetId")).getString("status").equals("deleted")&&!copied.exists(),"checked recycle tombstones the exact target");File retained=new File(Environment.getExternalStorageDirectory(),".PapersRecycle/"+recycledId+"/copy.txt");check(retained.exists()&&new String(java.nio.file.Files.readAllBytes(retained.toPath()),"UTF-8").equals("original"),"recycle retains original bytes");long deletedRevision=targets.resolve(copyRef.getString("targetId")).getLong("revision");write(copied,"replacement");boolean restoreRefused=false;try{targets.restore(copyRef.getString("targetId"),deletedRevision);}catch(Exception expected){restoreRefused=true;}check(restoreRefused&&retained.exists(),"restore refuses an occupied original path");if(!copied.delete())throw new IOException("Fixture replacement cleanup failed");JSONObject restored=targets.restore(copyRef.getString("targetId"),deletedRevision);check(restored.getString("status").equals("present")&&copied.exists()&&new String(java.nio.file.Files.readAllBytes(copied.toPath()),"UTF-8").equals("original"),"AYG restore recovers exact phone bytes");
 output.putString("result",new JSONObject().put("passed",passed).put("checks",checks).toString());
 }catch(Exception e){code=Activity.RESULT_CANCELED;output.putString("error",e.toString());output.putInt("passed",passed);}finally{if(peer!=null)try{peer.close();}catch(Exception ignored){}if(recycledId!=null)clean(new File(Environment.getExternalStorageDirectory(),".PapersRecycle/"+recycledId));if(fixture.getName().startsWith("PapersTargetCheck-")&&fixture.getParentFile().getName().equals("Download")){clean(fixture);try{SQLiteDatabase db=PhoneTargets.get(getTargetContext()).targetDatabase();db.delete("targets","path LIKE ?",new String[]{fixture.getAbsolutePath()+"/%"});}catch(Exception ignored){}}}finish(code,output);}
}
